-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): sim.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/sim.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   validator_rules_refused graded the number of broken specifications the
--   validator refuses, 7. The fixture holds seven deliberately broken specs and
--   every one is refused by construction, and the Validation view prints 'Rules
--   exercised 7' as a tile, so the tile is the answer (B5 finding 4). The field
--   now grades the error messages the validator raises across the seven cases,
--   8, which the learner counts from the message lists the same Validation view
--   prints under each case (one case, the missing start date, is coupled to a
--   second rule and raises two). No tile prints the count. The
--   working-the-capstone lesson that printed 'the message count is eight' is
--   rewritten to the method.
--   RE-KEY validator_rules_refused (expected 7, tol 0)
--       -> validator_error_messages 'Validator error messages across the seven cases' count, expected 8.0, tol 0.0
--   PROMPT was: Then count how many of the fixture's deliberately broken
--   specifications the validator refuses, counting CASES rather than error
--   messages.
--   PROMPT now: Then count the error messages the validator raises across the
--   fixture's seven deliberately broken specifications, every MESSAGE it lists
--   under each case.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: sim/advanced. Before it
-- writes, the file counts academy_capstone_attempts on each and REFUSES if any
-- exist, unless D5 allowlists that tier with the exact attempt ids (allowlist:
-- empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- sim / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'sim' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 sim refused: sim/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '32345addb0ba4de75544269b551ed943' and fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_rules_refused", "tol": 0, "unit": "count", "label": "Broken specifications refused", "expected": 7}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb then 'old'
              when md5(prompt) = 'd2d34142dca44cb9cfee4f3fbc8d9ef7' and fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_error_messages", "tol": 0.0, "unit": "count", "label": "Validator error messages across the seven cases", "expected": 8.0}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb then 'new'
              when md5(prompt) = 'a5200f28c432cd79706513f80a818c70' and fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_error_messages", "tol": 0.0, "unit": "count", "label": "Validator error messages across the seven cases", "expected": 8.0}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'sim' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w1 sim refused: sim/advanced matches neither its published form (prompt md5 32345addb0ba4de75544269b551ed943) nor its W1 form (prompt md5 d2d34142dca44cb9cfee4f3fbc8d9ef7), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 sim: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 sim refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'sim' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'sim/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'sim/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 sim refused: sim/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 sim: sim/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 sim refused: sim/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Build the parts of the Ekene deck that require a decision. First intersect the Ekene-6 side-track against the grid: it runs from a heel at map position (1900, 1800) to a toe at (1500, 2100), descending from the top of the sand to the base of the column, on a 100 m grid whose origin sits half a cell south-west of the field origin. Report the number of merged connections and the number of distinct (i, j) columns they fall in. Then calibrate: bisect on the kriging regional mean, in metres true vertical depth, until the deck''s CELL-CENTRE oil volume lands on the NG5 booking of 12139208.107496763 stb, and report the mean you converge on. Then build the history: convert the RC4 monthly ledger to rates by each period''s own calendar day count, and report the total oil the 36 periods carry when each rate is multiplied back by the days it spans. Then count the error messages the validator raises across the fixture''s seven deliberately broken specifications, every MESSAGE it lists under each case. Finally report the equilibration datum depth in feet, which is computed as the mean of all 900 column top depths rather than chosen.',
           fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_error_messages", "tol": 0.0, "unit": "count", "label": "Validator error messages across the seven cases", "expected": 8.0}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb
     where app_slug = 'sim' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 sim refused: sim/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd2d34142dca44cb9cfee4f3fbc8d9ef7' and fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_error_messages", "tol": 0.0, "unit": "count", "label": "Validator error messages across the seven cases", "expected": 8.0}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb)
        or (md5(prompt) = 'a5200f28c432cd79706513f80a818c70' and fields = '[{"key": "deviated_connection_count", "tol": 0, "unit": "count", "label": "Side-track merged connections", "expected": 11}, {"key": "deviated_distinct_columns", "tol": 0, "unit": "count", "label": "Side-track distinct columns", "expected": 8}, {"key": "calibration_regional_mean_m", "tol": 0.005, "unit": "m TVD", "label": "Calibrated kriging regional mean", "expected": 1570.026311}, {"key": "history_total_oil_stb", "tol": 50, "unit": "stb", "label": "History oil total, round trip", "expected": 176923.83644033302}, {"key": "validator_error_messages", "tol": 0.0, "unit": "count", "label": "Validator error messages across the seven cases", "expected": 8.0}, {"key": "equil_datum_depth_ft", "tol": 0.05, "unit": "ft", "label": "Equilibration datum depth", "expected": 5129.97013005754}]'::jsonb) from public.academy_capstones where app_slug = 'sim' and tier = 'advanced' and active) is not true then
    raise exception 'w1 sim refused: sim/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 sim: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
